import java.nio.ByteBuffer;
import java.util.HexFormat;
import org.apache.kafka.common.message.SnapshotFooterRecord;
import org.apache.kafka.common.message.SnapshotHeaderRecord;
import org.apache.kafka.common.record.internal.MemoryRecords;

// Snapshot envelope batches generated by the same Kafka client as RecordsSnapshotWriter.
class SnapshotVectors {
  public static void main(String[] args) {
    for (MemoryRecords records : new MemoryRecords[] {
             MemoryRecords.withSnapshotHeaderRecord(0, 123, 2, ByteBuffer.allocate(4096),
                 new SnapshotHeaderRecord().setVersion((short) 0).setLastContainedLogTimestamp(99)),
             MemoryRecords.withSnapshotFooterRecord(2, 123, 2, ByteBuffer.allocate(4096),
                 new SnapshotFooterRecord().setVersion((short) 0))}) {
      ByteBuffer buf = records.buffer();
      byte[] bytes = new byte[buf.remaining()];
      buf.get(bytes);
      System.out.println(HexFormat.of().formatHex(bytes));
    }
  }
}
